<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import AlbumArtwork from '../../components/AlbumArtwork.vue';import{appApi}from'../../api/app';const route=useRoute(),item=ref({});onMounted(async()=>item.value=(await appApi.musicInfo(route.params.id)).result)</script>
